package com.example

import com.example.data.ExportData
import com.squareup.moshi.Moshi
import org.junit.Assert.*
import org.junit.Test

class ExampleUnitTest {
  @Test
  fun addition_isCorrect() {
    assertEquals(4, 2 + 2)
  }

