ubjectId":3,"dateString":"2026-10-10","status":"ATTENDED","slotId":25,"isExtra":false}],"settings":[{"key":"interval_night_enabled","value":"false"},{"key":"interval_evening_enabled","value":"false"},{"key":"interval_morning_enabled","value":"false"}],"tasks":[],"customPeriods":[{"id":1,"name":"Period 1","startTime":"03:55 PM","endTime":"04:45 PM"},{"id":2,"name":"Period 2","startTime":"04:45 PM","endTime":"05:35 PM"},{"id":3,"name":"Period 3","startTime":"05:40 PM","endTime":"06:30 PM"},{"id":4,"name":"Period 4","startTime":"06:35 PM","endTime":"07:25 PM"},{"id":5,"name":"Period 5","startTime":"07:30 PM","endTime":"08:20 PM"},{"id":6,"name":"Period 0","startTime":"03:00 PM","endTime":"03:50 PM"}]}"""
    val moshi = Moshi.Builder().build()
    val adapter = moshi.adapter(ExportData::class.java)
    val parsed = adapter.fromJson(json)

    assertNotNull(parsed)
    assertEquals(9, parsed!!.subjects.size)
    assertEquals(21, parsed.timetableSlots.size)
    assertEquals(6, parsed.customPeriods.size)
    assertEquals(3, parsed.settings.size)
    assertEquals(0, parsed.tasks.size)
    assertTrue(parsed.attendanceRecords.isNotEmpty())
    assertEquals("Machine Learning", parsed.subjects[0].name)
    assertEquals("Cryptography and Security", parsed.subjects[4].name)
  }
}

